import React from 'react';
import { Link } from 'react-router-dom';

function MovieCard({ movie }) {
  // movie.description이 배열이 아닐 경우를 대비한 안전장치
  const descriptionLines = Array.isArray(movie.description) ? movie.description : [];

  return (
    // Link에 className을 추가하여 카드 전체를 제어
    <Link to={`/movie/${movie.id}`} className="movie-card">
      {/* 영화 포스터 이미지 */}
      <img 
        src={movie.poster_path} 
        alt={movie.title} 
        className="movie-poster" 
      />
      
      {/* 마우스를 올렸을 때 나타날 정보 오버레이 */}
      <div className="movie-overlay">
        <div className="overlay-content">
          <h3 className="overlay-title">{movie.title}</h3>
          <div className="overlay-description">
            {descriptionLines.map((line, index) => (
              <p key={index}>{line}</p>
            ))}
          </div>
        </div>
      </div>
    </Link>
  );
}

export default MovieCard;
